import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();if(s.numDistinct("rabbbit","rabbit")!=3||s.numDistinct("babgbag","bag")!=5||s.numDistinct("a","aa")!=0||s.numDistinct("a","b")!=0)throw new AssertionError();for(int n=1;n<=8;n++)for(int x=0;x<(1<<n);x++){String a=word(n,x);for(int m=1;m<=3;m++)for(int y=0;y<(1<<m);y++){String b=word(m,y);int want=0;for(int mask=0;mask<(1<<n);mask++){StringBuilder z=new StringBuilder();for(int i=0;i<n;i++)if((mask&(1<<i))!=0)z.append(a.charAt(i));if(z.toString().equals(b))want++;}if(s.numDistinct(a,b)!=want)throw new AssertionError();}}if(s.numDistinct("a".repeat(999)+"b","c")!=0)throw new AssertionError();System.out.println("Samples and original edge/reference checks passed");}static String word(int n,int x){StringBuilder b=new StringBuilder();for(int i=0;i<n;i++)b.append((x&(1<<i))==0?'a':'b');return b.toString();}}